// internal/proxy/util.go line 145-150
func isAlpha(c byte) bool {
    if (c < 'A' || c > 'Z') && (c < 'a' || c > 'z') {
        return false
    }
    return true
}

func isNumber(c byte) bool {
    if c < '0' || c > '9' {
        return false
    }
    return true
}

// internal/proxy/util.go line 1696-1698
func validCharInIndexName(c byte) bool {
    return c == '_' || c == '[' || c == ']' || isAlpha(c) || isNumber(c)
}

